 get pageSubtitle(){if(this.activeTraining)return 'Asistencia y evidencia descriptiva · '+this.selectedSite.name;if(this.activeCommission)return this.activeCommission.subtitle;return ({dashboard:'Una mirada a lo importante para avanzar hacia una operación más segura.',faenas:'Administra tus espacios de trabajo y consulta faenas chilenas de referencia.',reuniones:'Prepara la agenda, reúne al equipo y da continuidad a los acuerdos.',actas:'La memoria de tu comité, organizada y siempre a mano.',acuerdos:'Cada compromiso tiene una persona responsable y una fecha de entrega.',integrantes:'Personas ficticias, representación y responsabilidades de ejemplo.',inspecciones:'Registra lo observado en terreno y sigue cada acción hasta su verificación.',accidentes:'Consulta eventos ficticios y registra notas cronológicas descriptivas por faena.',capacitaciones:'Organiza actividades formativas de ejemplo para esta faena.',comisiones:'Registra los equipos de trabajo y sus objetivos en este espacio.',documentos:'Metadatos de documentos de ejemplo, organizados en un solo lugar.',asistente:'Prepara reuniones y explora respuestas locales de demostración.',reportes:'Indicadores calculados sobre registros sintéticos de este entorno.',configuracion:'Preferencias locales para tu espacio de demostración.'} as Record<string,string>)[this.page];}
 get heroBackground(){if(this.page==='dashboard')return 'linear-gradient(100deg,rgba(10,34,57,.97) 0%,rgba(10,34,57,.86) 42%,rgba(10,34,57,.44) 100%),url("/assets/faenalert-prevencion-colaborativa.webp")';if(this.page==='faenas')return 'linear-gradient(90deg,rgba(20,40,63,.96),rgba(20,40,63,.66) 51%,rgba(20,40,63,.18)),url("/assets/faenas/faena-chuquicamata.jpg")';if(!this.selectedSite.image)return 'linear-gradient(110deg,#14283f,#38546f)';return `linear-gradient(90deg,rgba(20,40,63,.96),rgba(20,40,63,.64) 51%,rgba(20,40,63,.08)),url('${this.selectedSite.image}')`;}
 get nextMeeting():RecordItem|undefined{return [...this.data.meetings].filter(r=>r.status==='Programada').sort((a,b)=>a.date.localeCompare(b.date))[0]||this.data.meetings[0];}
