 onSearchChange(value:string){this.search=value;this.searchResults.set([]);const term=value.trim();this.searchError.set(term.length<2?'Escribe al menos dos caracteres para buscar.':'Buscando…');const request=++this.searchRequest;if(this.searchTimer)clearTimeout(this.searchTimer);if(term.length<2)return;this.searchTimer=setTimeout(()=>void this.fetchSearchResults(term,request),350);}
 private async fetchSearchResults(term:string,request:number){const site=this.ui.context.siteId();if(!site){if(request===this.searchRequest)this.searchError.set('Selecciona una faena para buscar.');return;}try{const result=await this.ui.api.request<{items:WorkspaceSearchResult[]}>('sites/'+site+'/search','POST',{q:term});if(request===this.searchRequest){this.searchResults.set(result.items);this.searchError.set('');}}catch{if(request===this.searchRequest){this.searchResults.set([]);this.searchError.set('No fue posible completar la búsqueda.');}}}
 async selectFirstSearchResult(){if(!this.searchResults().length&&this.search.trim().length>=2){if(this.searchTimer)clearTimeout(this.searchTimer);const request=++this.searchRequest;await this.fetchSearchResults(this.search.trim(),request);}const result=this.searchResults()[0];if(result)this.selectSearchResult(result);}
 selectSearchResult(result:WorkspaceSearchResult){const member=result.entity==='member'?result.record:null;const item=member?null:this.searchRecord(result);this.go(result.page);this.search='';this.searchResults.set([]);this.searchError.set('');if(result.page==='inspecciones'){setTimeout(()=>this.preventionModule?.open(result.id),0);return;}if(member){let row=this.data.members.find(m=>m.apiId===String(member.id));if(!row){row={id:Math.max(0,...this.data.members.map(m=>m.id))+1,apiId:String(member.id),version:member.version,name:member.name,job:member.job||'Cargo no informado',representation:member.member_kind==='PREVENTION_EXPERT'?'Asesoría técnica':member.representation==='WORKER'?'Trabajadores':'Empresa',role:member.role||'Integrante',type:member.member_kind==='PREVENTION_EXPERT'?'Asesor sin voto':member.participation==='PRINCIPAL'?'Titular':'Suplente',email:member.contact_email||'',status:member.valid_until&&String(member.valid_until).slice(0,10)<localDate()?'Histórico':'Activo'};this.data.members=[...this.data.members,row];}this.query=row.name;return;}if(item){const collection=({reuniones:'meetings',actas:'minutes',acuerdos:'actions',accidentes:'incidents',documentos:'documents',capacitaciones:'trainings',comisiones:'commissions'} as Record<string,Collection>)[result.page];if(collection&&!this.data[collection].some(existing=>existing.apiId===item.apiId))this.data={...this.data,[collection]:[item,...this.data[collection]]};this.query=item.title;}}
 private searchRecord(result:WorkspaceSearchResult):RecordItem{const raw=result.record;const collection=({reuniones:'meetings',actas:'minutes',acuerdos:'actions',accidentes:'incidents',documentos:'documents',capacitaciones:'trainings',comisiones:'commissions'} as Record<string,Collection>)[result.page];const id=collection?Math.max(0,...this.data[collection].map(r=>r.id))+1:1;const common={id,apiId:String(raw.id),version:raw.version,title:raw.title,subtitle:result.subtitle||'',owner:'Equipo de la faena',date:String(raw.created_at||'').slice(0,10),status:'Registrada',type:'Registro'};switch(result.entity){case 'meeting':return {...common,apiStatus:raw.status,scheduledAt:raw.scheduled_at,location:raw.location,agenda:raw.agenda,date:String(raw.scheduled_at).slice(0,10),status:raw.status==='IN_PROGRESS'?'En curso':raw.status==='COMPLETED'?'Finalizada':'Programada',owner:'Comité de demostración',type:raw.title.toLowerCase().includes('extraordinaria')?'Extraordinaria':'Ordinaria',notes:raw.agenda};case 'minute':return {...common,relatedApiId:raw.meeting_id||undefined,status:raw.status==='IN_REVIEW'?'Por revisar':'Borrador',owner:'Secretaría de demostración',type:'Acta',notes:raw.content};case 'action':return {...common,apiStatus:raw.apiStatus,sourceCode:raw.sourceCode,relatedApiId:raw.relatedApiId,ownerId:raw.ownerId,owner:raw.owner,date:String(raw.date).slice(0,10),status:raw.status,type:raw.type,priority:raw.priority};case 'incident':return {...common,apiStatus:raw.kind,subtitle:raw.location,status:'Registro de demostración',date:String(raw.occurred_at).slice(0,10),type:raw.kind==='ACCIDENT'?'Accidente':raw.kind==='OBSERVATION'?'Observación':'Incidente',priority:'Media',notes:raw.facts,location:raw.location};case 'document':return {...common,subtitle:raw.description||result.subtitle,status:'Vigente',date:String(raw.created_at).slice(0,10),type:'Documento'};case 'training':return {...common,subtitle:raw.description,scheduledAt:raw.scheduled_at,date:String(raw.scheduled_at).slice(0,10),owner:raw.instructor,type:'Capacitación',notes:raw.description};case 'commission':return {...common,subtitle:raw.objective,date:String(raw.created_at).slice(0,10),owner:'Comité de demostración',type:'Comisión',notes:raw.objective};default:return common;}}
