 go(p:string){this.page=p;this.query='';this.search='';this.searchResults.set([]);this.searchError.set('');this.searchRequest++;if(this.searchTimer)clearTimeout(this.searchTimer);this.filter='Todos';this.activeMeeting=null;this.activeMinute=null;this.activeIncident=null;this.activeTraining=null;this.activeCommission=null;this.trainingParticipants=[];this.trainingEvidence=[];this.commissionActions.set([]);this.mobileNav=false;this.menu=false;location.hash=p;window.scrollTo({top:0,behavior:'smooth'});if(p==='faenas'&&this.ui.context.isPlatformAdmin())void this.refreshWorkspaceDirectory();}
