 async enterDemo(){this.showLanding.set(false);this.loginEmail='demo@faenalert.local';this.password='';this.authError='';if(this.ui.session.token()){this.authChecking.set(true);try{await this.ui.run(()=>this.loadWorkspace());if(this.ui.error()){this.ui.session.clear();this.ui.context.clear();this.authError='La sesión local venció. Ingresa de nuevo para continuar.';this.loggedIn=false;return;}this.loggedIn=true;this.go('dashboard');}finally{this.authChecking.set(false);}}else{this.authChecking.set(false);this.loggedIn=false;}}
