 async openMeeting(r:RecordItem){this.go('reuniones');this.activeMeeting=r;this.tab='Agenda';const parts=(r.agenda||'Seguimiento de acuerdos; Revisión preventiva; Próximos compromisos').split(/[;\n]+/).map(t=>t.trim()).filter(Boolean);this.checkedAgenda=new Set(parts.flatMap((part,index)=>/^\[x\]/i.test(part)?[index]:[]));this.agenda=parts.map(part=>part.replace(/^\[[ xX]\]\s*/,''));this.attendance=new Set();await this.ui.run(async()=>{const result=await this.ui.api.request<{items:{member_id:string;present:boolean}[]}>('meetings/'+r.apiId+'/attendance');this.attendance=new Set(result.items.filter(item=>item.present).map(item=>this.data.members.find(member=>member.apiId===item.member_id)?.id).filter((id):id is number=>id!==undefined));});if(this.ui.error())this.notify(this.ui.error());}
 async openTraining(r:RecordItem){this.go('capacitaciones');this.activeTraining=r;this.participantName='';this.trainingEvidenceDescription='';this.formError='';await this.ui.run(()=>this.loadTrainingDetail(r));if(this.ui.error())this.notify(this.ui.error());}
