 constructor(){effect(()=>{if(this.ui.session.expired()){this.authError='Tu sesión venció. Ingresa de nuevo para continuar. Los borradores de acta guardados localmente se conservaron.';this.clearAuthenticatedState();}});try{const saved=JSON.parse(localStorage.getItem('faenalert.preferences')||'null');if(saved?.company==='Empresa de demostración'&&String(saved?.email).endsWith('@demo.local'))this.settings=saved;}catch{}window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==this.page&&this.nav.some(n=>n[0]===p))this.go(p);});const hash=location.hash.slice(1);if(this.nav.some(n=>n[0]===hash))this.page=hash;if(this.ui.session.token())void this.enterDemo();}
